// P3-8: daily weather for a zone. Pure and repeatable: the same zone on the same day always has the same weather, with
// no stored state and no Math.random, so going back to an earlier date shows what it showed before.
//
// Weather moves in fronts. Each zone has a moisture level that drifts smoothly between random values a few days apart,
// and the day's condition is where that level falls on a ladder from driest to wettest. A rising level walks up the
// ladder (clear, cloud, overcast, rain), which is clouds building into a downpour. The drift is shaped so that moisture
// is still evenly spread over time, so in the long run each condition comes up as often as its climate table says.
import { absoluteDayToDate, type CalendarDefinition } from './calendar.ts';
import {
  CLIMATE_TABLES,
  TEMPERATURE_BANDS,
  WEATHER_CONDITIONS,
  WEATHER_SEASONS,
  WIND_LEVELS,
  type Climate,
  type TemperatureBand,
  type WeatherCondition,
  type WeatherSeason,
  type WindLevel,
} from './weatherData.ts';

/** Is the weather heading somewhere? A hint for the table, read from the next two days. */
export type WeatherTrend = 'building' | 'easing' | 'steady';

export interface DayWeather {
  condition: WeatherCondition;
  temperature: TemperatureBand;
  wind: WindLevel;
  trend: WeatherTrend;
}

export interface WeatherInput {
  campaignId: string;
  zoneId: string;
  day: number;
  climate: Climate;
  season: WeatherSeason;
}

// DRIEST TO WETTEST. Each table's percentages are laid along this ladder, so moisture picks a step.
const WETNESS: readonly WeatherCondition[] = [
  'dust_wind',
  'clear',
  'partly_cloudy',
  'overcast',
  'fog',
  'drizzle',
  'rain',
  'sleet',
  'snow',
  'hail',
  'storm',
  'blizzard',
];
const PRECIPITATION: ReadonlySet<WeatherCondition> = new Set([
  'drizzle',
  'rain',
  'sleet',
  'snow',
  'hail',
  'storm',
  'blizzard',
]);

/** How many days between a stream's random values: fronts take days, wind turns in a couple. */
const SPAN = { moisture: 4, temperature: 6, wind: 2 } as const;

/** FNV-1a with a final mix: a repeatable hash of text to a 32-bit number. */
function hash(text: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  h ^= h >>> 13;
  h = Math.imul(h, 0x5bd1e995);
  h ^= h >>> 15;
  return h >>> 0;
}

const uniform = (seed: string) => hash(seed) / 4294967296;

/** Share of a blend of two even random numbers (weights w and 1 - w) that falls below x. Evens the blend back out. */
function blendShare(x: number, w: number): number {
  const lo = Math.min(w, 1 - w);
  const hi = 1 - lo;
  if (lo === 0) return x;
  if (x <= lo) return (x * x) / (2 * lo * hi);
  if (x <= hi) return (2 * x - lo) / (2 * hi);
  return 1 - ((1 - x) * (1 - x)) / (2 * lo * hi);
}

/** A level from 0 to 1 that drifts between random values `span` days apart, and over time is evenly spread. */
function drift(seed: string, day: number, span: number): number {
  const index = Math.floor((day - 1) / span);
  const t = ((day - 1) % span) / span;
  const from = uniform(`${seed}|${index}`);
  const to = uniform(`${seed}|${index + 1}`);
  return blendShare(from * (1 - t) + to * t, t);
}

/** The outcome whose slice of the percentages holds this level. */
function pick<T extends string>(order: readonly T[], weightOf: (outcome: T) => number, level: number): T {
  const target = level * 100;
  let total = 0;
  let last = order[0];
  for (const outcome of order) {
    const weight = weightOf(outcome);
    if (weight > 0) last = outcome;
    total += weight;
    if (weight > 0 && target < total) return outcome;
  }
  return last;
}

function atLeast(wind: WindLevel, least: WindLevel): WindLevel {
  return WIND_LEVELS.indexOf(wind) < WIND_LEVELS.indexOf(least) ? least : wind;
}

function atMost(band: TemperatureBand, most: TemperatureBand): TemperatureBand {
  return TEMPERATURE_BANDS.indexOf(band) > TEMPERATURE_BANDS.indexOf(most) ? most : band;
}

/** Makes the three separate rolls agree: no hot blizzards, no rain below freezing, no still storms. */
function reconcile(rolled: Omit<DayWeather, 'trend'>): Omit<DayWeather, 'trend'> {
  let { condition, temperature, wind } = rolled;
  if (temperature === 'freezing') {
    if (condition === 'drizzle' || condition === 'rain') condition = 'snow';
    if (condition === 'storm') condition = 'blizzard';
  }
  if (condition === 'snow' || condition === 'blizzard' || condition === 'sleet')
    temperature = atMost(temperature, 'cold');
  if (condition === 'storm' || condition === 'blizzard' || condition === 'dust_wind') wind = atLeast(wind, 'strong');
  return { condition, temperature, wind };
}

function rollDay({ campaignId, zoneId, day, climate, season }: WeatherInput): Omit<DayWeather, 'trend'> {
  const tables = CLIMATE_TABLES[climate][season];
  const seed = (stream: string) => `${campaignId}|${zoneId}|${stream}`;
  const chance =
    <T extends string>(keys: readonly T[], row: readonly number[]) =>
    (k: T) =>
      row[keys.indexOf(k)];
  return reconcile({
    condition: pick(WETNESS, chance(WEATHER_CONDITIONS, tables.condition), drift(seed('moisture'), day, SPAN.moisture)),
    temperature: pick(
      TEMPERATURE_BANDS,
      chance(TEMPERATURE_BANDS, tables.temperature),
      drift(seed('heat'), day, SPAN.temperature),
    ),
    wind: pick(WIND_LEVELS, chance(WIND_LEVELS, tables.wind), drift(seed('wind'), day, SPAN.wind)),
  });
}

/** The weather of one zone on one day. */
export function weatherFor(input: WeatherInput): DayWeather {
  const today = rollDay(input);
  const wet = (w: Omit<DayWeather, 'trend'>) => PRECIPITATION.has(w.condition);
  const after = (days: number) => rollDay({ ...input, day: input.day + days });
  let trend: WeatherTrend = 'steady';
  if (!wet(today) && (wet(after(1)) || wet(after(2)))) trend = 'building';
  else if (wet(today) && !wet(after(1))) trend = 'easing';
  return { ...today, trend };
}

/** Which of the four weather seasons a day is in. Without a calendar, a year is four seasons of 91 days. */
export function weatherSeason(calendar: CalendarDefinition | null, day: number): WeatherSeason {
  if (!calendar) return WEATHER_SEASONS[Math.floor(((day - 1) % 364) / 91)];
  const date = absoluteDayToDate(calendar, day);
  const named = date.season?.toLowerCase();
  const direct = WEATHER_SEASONS.find(s => s === named);
  if (direct) return direct;
  const index = calendar.seasons.findIndex(s => s.name === date.season);
  if (index >= 0) return WEATHER_SEASONS[index % 4];
  return WEATHER_SEASONS[Math.floor((date.monthIndex * 4) / calendar.months.length)];
}

// ZONES ON MAPS ----------------------------------------------------------------------------

export interface Point {
  x: number;
  y: number;
}

export interface ZoneShape extends Point {
  id: string;
  radius: number;
  /** Any text that sorts by time, such as an ISO date. */
  createdAt: string;
}

/** The zone at a point. Where zones overlap the smallest wins, and a tie goes to the one created later. */
export function zoneAt<Z extends ZoneShape>(point: Point, zones: readonly Z[]): Z | null {
  const covering = zones.filter(z => (z.x - point.x) ** 2 + (z.y - point.y) ** 2 <= z.radius ** 2);
  return [...covering].sort((a, b) => a.radius - b.radius || b.createdAt.localeCompare(a.createdAt))[0] ?? null;
}

export interface WeatherMapLink {
  id: string;
  parentPinId: string | null;
  parentRegionId: string | null;
}

/** With no position, or one outside every zone, a map uses its widest zone (the earliest of equals). */
function defaultZone<Z extends ZoneShape>(zones: readonly Z[]): Z | null {
  return [...zones].sort((a, b) => b.radius - a.radius || a.createdAt.localeCompare(b.createdAt))[0] ?? null;
}

/**
 * The zone a map takes its weather from. A map with zones uses the zone at the position, or its default. A map with
 * none climbs to its parent, at the pin or region that leads down to it, and so on up to the top.
 */
export function weatherForMap<Z extends ZoneShape>(
  map: WeatherMapLink,
  mapsById: Readonly<Record<string, WeatherMapLink & { parentMapId: string | null }>>,
  zonesByMap: Readonly<Record<string, readonly Z[]>>,
  pinsAndRegionsById: Readonly<Record<string, Point>>,
  position: Point | null = null,
): Z | null {
  const seen = new Set<string>();
  let current: WeatherMapLink = map;
  let at = position;
  while (!seen.has(current.id)) {
    seen.add(current.id);
    const zones = zonesByMap[current.id] ?? [];
    if (zones.length > 0) return (at && zoneAt(at, zones)) || defaultZone(zones);
    const link = current.parentPinId ?? current.parentRegionId;
    const parent = mapsById[current.id]?.parentMapId ?? null;
    if (!link || !parent || !mapsById[parent]) return null;
    at = pinsAndRegionsById[link] ?? null;
    current = mapsById[parent];
  }
  return null;
}

// NOTES FOR THE DM -------------------------------------------------------------------------

/** Suggestions for the table in plain words. Never rules: the DM decides what, if anything, applies. */
export function dmNotes(
  weather: Pick<DayWeather, 'condition' | 'temperature' | 'wind'> & Partial<DayWeather>,
): string[] {
  const notes: string[] = [];
  const add = (n: string) => notes.push(n);
  switch (weather.condition) {
    case 'fog':
      add('Fog: consider limiting how far anyone can see, and making it easy to get lost.');
      break;
    case 'rain':
      add('Rain: consider making distant sounds harder to hear and open flames harder to keep lit.');
      break;
    case 'storm':
      add('Storm: consider limiting sight and hearing checks, and making camp or open travel risky.');
      break;
    case 'snow':
      add('Snow: consider slower travel over open ground, and tracks that are easy to follow.');
      break;
    case 'blizzard':
      add('Blizzard: consider that travel may stop, shelter may matter, and sight may be down to a few paces.');
      break;
    case 'sleet':
      add('Sleet: consider slippery footing and a miserable, quiet march.');
      break;
    case 'hail':
      add('Hail: consider a sharp, short danger to anyone caught in the open, and to the horses.');
      break;
    case 'dust_wind':
      add('Dust wind: consider limiting sight, and asking who has covered their eyes and mouth.');
      break;
    default:
      break;
  }
  if (weather.temperature === 'freezing') add('Freezing: consider asking who has warm clothing or a fire tonight.');
  if (weather.temperature === 'scorching') add('Scorching: consider asking how much water the party is carrying.');
  if (weather.wind === 'gale')
    add('Gale: consider trouble for ranged attacks, small boats and anything not tied down.');
  if (weather.trend === 'building')
    add('The weather is turning: clouds are building, and rain or snow is likely within two days.');
  if (weather.trend === 'easing') add('The weather is easing: expect it to clear by tomorrow.');
  return notes;
}
